// What broke, where, and a link to the failed run. Never the run's data: a client's message can sit in a step's
// output, so only the workflow name, the step and a shortened error message are shown.
const e = $('A workflow failed').first().json;
const run = e.execution; // missing when the workflow failed before it started (its trigger broke)
const error = run?.error ?? e.trigger?.error ?? {};

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const short = (t, max) => {
  const s = String(t ?? '').replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
};

const workflow = esc(e.workflow?.name ?? 'A workflow');
const where = run?.lastNodeExecuted
  ? ` at step *${esc(run.lastNodeExecuted)}*`
  : e.trigger ? ' before it could start (its trigger failed)' : '';
const message = esc(short(error.message || error.description || 'No error message', 300)).replace(/`/g, "'");
// Only a plain http(s) address becomes a link; anything else is left out.
const link = /^https?:\/\/[^\s<>|]+$/.test(run?.url ?? '') ? `\n<${run.url}|Open the failed run>` : '';

return [{ json: { text: `:rotating_light: *${workflow}* failed${where}\n\`${message}\`${link}` } }];
